    description: {
      de: "Kiskunhalas ist weltberühmt für seine handgefertigte Spitze.",
      hu: "Kiskunhalas világhírű a kézzel készített csipkéjéről.",
      ro: "Kiskunhalas este faimos în întreaga lume pentru dantela sa lucrată manual.",
      en: "Kiskunhalas is world-famous for its handmade lace."
    },
    descriptionAdvanced: {
      de: "Kiskunhalas ist eine Stadt im zentralen Teil von Südungarn, im Komitat Bács-Kiskun, und ist weltweit für seine Spitzenherstellung bekannt. Die Geschichte der Stadt reicht bis in das Mittelalter zurück, als sie ein Zentrum der Kumanen (Kun) war, die sich in der Region niederließen. Die bedeutendste kulturelle Errungenschaft ist die Halaser Spitze, die 1902 von Árpád Dékáni und Mária Markovits entwickelt wurde und heute als Hungaricum gilt. Die Architektur der Stadt spiegelt den bürgerlichen Wohlstand des späten 19. und frühen 20. Jahrhunderts wider, mit dem Rathaus und dem Spitzenhaus als markante Wahrzeichen. Neben der Kultur ist Kiskunhalas auch für seine Thermalbäder bekannt, deren Wasser aus einer Tiefe von über 1000 Metern an die Oberfläche tritt. Die Umgebung ist geprägt durch die typische Puszta-Landschaft, die Möglichkeiten für Reittourismus und Naturbeobachtungen bietet. Kiskunhalas dient als wichtiges Verwaltungs- und Bildungszentrum in der Region Kiskunság und pflegt intensiv seine historischen Traditionen.",
      hu: "Kiskunhalas Dél-Magyarország középső részén, Bács-Kiskun vármegyében található város, amely világszerte ismertté vált csipkeverő művészetéről. A település története a középkorig nyúlik vissza, amikor a térségben letelepedő kunok egyik központja volt. Legjelentősebb kulturális értéke a Halasi csipke, amely 1902-ben született meg Dékáni Árpád és Markovits Mária munkássága nyomán, és mára Hungarikummá vált. A város építészete a 19. század végi és 20. század eleji polgári jólétet tükrözi, a Városháza és a Csipkeház meghatározó látnivalók. Kiskunhalas a kultúra mellett gyógyfürdőjéről is nevezetes, amelynek vize több mint 1000 méter mélyről tör fel. A környéket a tipikus pusztai táj jellemzi, amely lehetőséget ad a lovasturizmusra és a természetjárásra. A város fontos közigazgatási és oktatási központ a Kiskunság szívében, és nagy hangsúlyt fektet történelmi hagyományainak ápolására.",
      ro: "Kiskunhalas este un oraș situat în partea centrală a Ungariei de Sud, în județul Bács-Kiskun, devenit celebru în întreaga lume pentru arta dantelei sale. Istoria localității se întinde până în Evul Mediu, când a fost unul dintre centrele cumanilor stabiliți în regiune. Cea mai importantă valoare culturală este Dantela de Halas, apărută în 1902 datorită muncii lui Árpád Dékáni și Mária Markovits, fiind astăzi considerată un Hungaricum. Arhitectura orașului reflectă prosperitatea burgheză de la sfârșitul secolului al XIX-lea și începutul secolului XX, Primăria și Casa Dantelor fiind atracții principale. Pe lângă cultură, Kiskunhalas este renumit și pentru băile sale termale, a căror apă țâșnește de la o adâncime de peste 1000 de metri. Împrejurimile sunt caracterizate de peisajul tipic de pustă, oferind oportunități pentru turismul ecvestru și drumeții. Orașul este un centru administrativ și educațional important în inima regiunii Kiskunság, punând mare accent pe păstrarea tradițiilor istorice.",
      en: "Kiskunhalas is a city in the central part of Southern Hungary, in Bács-Kiskun County, which has become world-famous for its lace-making art. The settlement's history dates back to the Middle Ages when it was one of the centers of the Cumans (Kun) who settled in the region. Its most significant cultural asset is the Halas Lace, born in 1902 through the work of Árpád Dékáni and Mária Markovits, and is now recognized as a Hungaricum. The city's architecture reflects the bourgeois prosperity of the late 19th and early 20th centuries, with the City Hall and the Lace House being defining landmarks. Besides culture, Kiskunhalas is notable for its thermal spa, whose water surfaces from a depth of over 1000 meters. The surroundings are characterized by typical Puszta landscapes, offering opportunities for equestrian tourism and nature walks. The city is an important administrative and educational center in the heart of Kiskunság and places great emphasis on nurturing its historical traditions.",
    },
