      hu: ["Szentes nevét először 1332-ben említették egy pápai tizedjegyzékben.", "A város alatt található Európa egyik legnagyobb kiterjedésű hévízmezője.", "A neoreneszánsz Megyeháza 1883-ban épült, ma is a városkép meghatározója.", "A Koszta József Múzeum jelentős avar kori régészeti gyűjteménnyel rendelkezik.", "Szentes a magyar vízilabdázás egyik nagy múltú fellegvára.", "A város környékén található az ország legnagyobb üvegházi gazdasága."],
      ro: ["Localitatea Szentes este atestată documentar pentru prima dată în anul 1332.", "Orașul deține unul dintre cele mai mari sisteme de încălzire geotermală din Europa.", "Clădirea neorenascentistă a prefecturii a fost inaugurată în anul 1883.", "Muzeul local poartă numele pictorului realist József Koszta.", "Canalul Kurca străbate centrul orașului, oferind un peisaj pitoresc.", "Szentes este renumit pentru echipa sa de polo pe apă, cu multiple titluri naționale."],
