      hu: ["A templom alapjai a 13. századból, a román stílus időszakából származnak.", "Az épület fő építőanyaga az égetett tégla volt.", "A templom a 16-17. századi török harcok során pusztult el.", "A rom leglátványosabb része a megmaradt nyugati homlokzat és toronyrész.", "Tiszaderzs települése a középkorban jelentős helyszín volt a Tisza mentén.", "A romot az elmúlt évtizedekben műemlékileg konzerválták."],
      ro: ["Biserica a fost ridicată inițial în secolul al XIII-lea în stil romanic.", "Materialul principal de construcție utilizat a fost cărămida arsă.", "Edificiul a fost distrus și abandonat în timpul ocupației otomane.", "Fațada vestică este cea mai bine conservată parte a ruinei actuale.", "Monumentul se află în localitatea Tiszaderzs, lângă lacul Tisa.", "Studiile arheologice indică extinderi realizate în stil gotic ulterior."],
      en: ["The church was originally built in the 13th century in the Romanesque style.", "The primary building material used for the structure was fired brick.", "The church was ruined during the Ottoman-Hungarian wars in the 16th-17th centuries.", "The most prominent remaining part is the western facade and tower section.", "The ruins are located in the village of Tiszaderzs in Jász-Nagykun-Szolnok County.", "Archaeological evidence shows that the church was later expanded in Gothic style."],
