    descriptionAdvanced: {
      de: "Pásztó ist eine geschichtsträchtige Kleinstadt im Komitat Nógrád, am westlichen Fuße des Mátra-Gebirges gelegen. Die Siedlung ist seit dem 11. Jahrhundert bekannt und war ein bedeutendes religiöses Zentrum, als König Béla III. im Jahr 1190 eine Zisterzienserabtei gründete. Das historische Zentrum von Pásztó bewahrt wertvolle mittelalterliche Baudenkmäler, darunter das spätgotische Schulmeisterhaus (Oskolamester háza) und die restaurierte Klosterruine. Im Mittelalter war die Stadt für ihren Weinhandel und ihre Handwerkerzünfte berühmt, was ihr wirtschaftliches Wachstum förderte. Die barocke katholische Kirche und das ehemalige Zisterzienserkloster prägen heute das Stadtbild und beherbergen Ausstellungen zur Stadtgeschichte und zur Arbeit der Mönche. Durch seine Lage am Zagyva-Tal dient Pásztó als Tor zum westlichen Mátra-Gebirge und ist ein idealer Ausgangspunkt für Wanderungen und Naturerkundungen.",
      hu: "Pásztó nagy múltú kisváros Nógrád vármegyében, a Mátra hegység nyugati lábánál, a Zagyva völgyében fekszik. A település már a 11. században létezett, de igazi jelentőségét akkor nyerte el, amikor III. Béla király 1190-ben ciszterci apátságot alapított itt. Pásztó történelmi belvárosa rendkívül értékes középkori emlékeket őriz, mint például a késő gótikus Oskolamester házát és a helyreállított kolostoregyüttest. A középkorban a város híres volt borkereskedelméről és kézműves céheiről, ami biztosította gazdasági felemelkedését. A barokk stílusú katolikus templom és a volt kolostor épülete ma múzeumként működik, bemutatva a város fejlődését és a szerzetesek mindennapjait. A város földrajzi elhelyezkedése révén a Mátra egyik fontos kapuja, népszerű kiindulópont a túrázók és a természet szerelmesei számára.",
      ro: "Pásztó este un oraș mic cu o istorie bogată în județul Nógrád, situat la poalele vestice ale munților Mátra, în valea Zagyva. Așezarea exista deja în secolul al XI-lea, dar a câștigat importanță reală când regele Béla al III-lea a fondat o abație cisterciană aici în 1190. Centrul istoric din Pásztó păstrează monumente medievale extrem de valoroase, cum ar fi Casa Maestrului Școlii (Oskolamester háza) în stil gotic târziu și ansamblul mănăstiresc restaurat. În Evul Mediu, orașul era renumit pentru comerțul cu vin și breslele de meșteșugari, ceea ce a asigurat ascensiunea sa economică. Biserica catolică barocă și clădirea fostei mănăstiri funcționează astăzi ca muzeu, prezentând dezvoltarea orașului și viața de zi cu zi a călugărilor. Datorită locației sale geografice, Pásztó este o poartă importantă către Mátra, fiind un punct de plecare popular pentru drumeții.",
      en: "Pásztó is a small town with a rich history in Nógrád County, located at the western foot of the Mátra Mountains in the Zagyva Valley. The settlement existed as early as the 11th century, but it gained real significance when King Béla III founded a Cistercian abbey here in 1190. Pásztó's historic center preserves exceptionally valuable medieval monuments, such as the late-Gothic Schoolmaster's House (Oskolamester háza) and the restored monastery complex. In the Middle Ages, the town was famous for its wine trade and craft guilds, which ensured its economic rise. The Baroque Catholic church and the former monastery building now operate as a museum, showcasing the town's development and the daily lives of the monks. Geographically, Pásztó serves as an important gateway to the Mátra Mountains and is a popular starting point for hikers and nature enthusiasts.",
    },
