      hu: ["Az 1664-es béke helyszíne.", "Régi dominikánus kolostor.", "Egykori vármegyeszékhely.", "A Hegyhát kapuja."],
      ro: ["Locul păcii din 1664.", "Veche mănăstire dominicană.", "Fostă reședință de județ.", "Poarta către Hegyhát."],
