      hu: ["Vasvár a középkorban Vas vármegye első székhelye volt.", "A híres vasvári békét 1664. augusztus 10-én írták alá.", "A domonkos rendi kolostort a 13. század közepén alapították.", "A városban áll a Békeangyal szobor az 1664-es események emlékére.", "Vasvár közelében húzódott egykor a római kori borostyánkő út.", "A város plébániatemploma eredetileg román stílusban épült a 13. században."],
