    description: {
      de: "Berhida ist eine kleine Stadt in der Nähe des Balaton.",
      hu: "Berhida kisváros a Balaton közelében.",
      ro: "Berhida este un orășel situat în apropiere de Balaton.",
      en: "Berhida is a small town near Lake Balaton."
    },
    descriptionAdvanced: {
      de: "Berhida ist eine Kleinstadt im östlichen Teil des Komitats Veszprém, am Zusammenfluss der Bäche Séd und Sényő gelegen. Die Siedlung hat eine lange Geschichte, die bis in die Römerzeit zurückreicht, was durch archäologische Funde in der Umgebung belegt ist. Das bedeutendste Baudenkmal ist die im 13. Jahrhundert errichtete römisch-katholische Kirche des Heiligen Ladislaus, die für ihr einzigartiges Steindach und ihre romanische Architektur bekannt ist. Im Jahr 1985 wurde die Stadt durch ein schweres Erdbeben der Stärke 5,2 erschüttert, das zahlreiche historische Gebäude beschädigte und zu umfangreichen Wiederaufbaumaßnahmen führte. Die wirtschaftliche Bedeutung der Stadt stieg im 20. Jahrhundert durch die Ansiedlung chemischer Industrien im benachbarten Peremarton. Heute ist Berhida ein wichtiges lokales Zentrum zwischen den Städten Veszprém und Székesfehérvár, das seine ländliche Atmosphäre bewahrt hat.",
      hu: "Berhida Veszprém vármegye keleti részén fekvő kisváros, a Séd és a Sényő-patak találkozásánál helyezkedik el. A település története a római korig nyúlik vissza, amit a környéken talált régészeti leletek is bizonyítanak. Legfontosabb műemléke a 13. században épült Szent László római katolikus templom, amely egyedülálló kőtetőjéről és középkori építészeti megoldásairól híres. 1985-ben a várost egy 5,2-es erősségű földrengés rázta meg, amely jelentős károkat okozott az épületállományban, és nagyszabású helyreállítási munkálatokat tett szükségessé. A 20. században a szomszédos Peremarton vegyiparának köszönhetően a település gazdasági jelentősége megnőtt. Ma Berhida Veszprém és Székesfehérvár között fontos helyi központ, amely megőrizte kisvárosias jellegét és gazdag történelmi örökségét.",
      ro: "Berhida este un oraș mic situat în partea de est a județului Veszprém, la confluența pâraielor Séd și Sényő. Așezarea are o istorie îndelungată care datează din epoca romană, fapt dovedit de numeroasele descoperiri arheologice din zonă. Cel mai important monument arhitectural este biserica romano-catolică Sfântul Ladislau, construită în secolul al XIII-lea, renumită pentru acoperișul său unic din piatră și elementele romanice. În anul 1985, orașul a fost lovit de un cutremur puternic cu magnitudinea de 5,2, care a avariat multe clădiri istorice și a necesitat eforturi masive de reconstrucție. Importanța economică a localității a crescut în secolul al XX-lea datorită industriei chimice din zona vecină Peremarton. Astăzi, Berhida servește ca un centru local important între orașele Veszprém și Székesfehérvár, păstrându-și atmosfera rurală.",
      en: "Berhida is a small town located in the eastern part of Veszprém County, at the confluence of the Séd and Sényő creeks. The settlement's history dates back to Roman times, as evidenced by archaeological finds in the surrounding area. Its most significant landmark is the 13th-century Roman Catholic Church of Saint Ladislaus, renowned for its unique stone-tiled roof and well-preserved medieval architecture. In 1985, the town was the epicenter of a major earthquake measuring 5.2 on the Richter scale, which caused extensive damage to historical structures and prompted significant reconstruction. During the 20th century, the town's economic importance grew due to the chemical industry established in neighboring Peremarton. Today, Berhida acts as a vital local hub between the cities of Veszprém and Székesfehérvár, maintaining its traditional character and historical heritage.",
    },
