    name: { de: "Kis-Balaton", hu: "Kis-Balaton", ro: "Micul Balaton", en: "Little Balaton" },
    description: {
      de: "Der Kis-Balaton ist ein riesiges Feuchtgebiet und Naturschutzgebiet am Westende des Balaton.",
      hu: "A Kis-Balaton egy hatalmas vizes élőhely és természetvédelmi terület a Balaton nyugati végénél.",
      ro: "Micul Balaton este o zonă umedă uriașă și o rezervație naturală la capătul vestic al Balatonului.",
      en: "The Little Balaton is a huge wetland and nature reserve at the western end of Lake Balaton."
    },
    descriptionAdvanced: {
      de: "Der Kleine Plattensee (Kis-Balaton) ist ein weitläufiges Feuchtgebiet und Naturschutzgebiet an der südwestlichen Spitze des Plattensees in Ungarn. Er war ursprünglich Teil des Sees, wurde aber im 19. Jahrhundert durch Regulierungsmaßnahmen weitgehend trockengelegt, was zu einer Verschlechterung der Wasserqualität des Plattensees führte. In den 1980er Jahren wurde ein großflächiges Wasserschutzsystem errichtet, um den Kleinen Plattensee als natürliches Filterbecken für den Fluss Zala wiederherzustellen. Heute umfasst das Gebiet etwa 14.700 Hektar und ist nach der Ramsar-Konvention als Feuchtgebiet von internationaler Bedeutung geschützt. Es ist ein Paradies für Ornithologen, da über 250 Vogelarten hier nisten oder rasten, darunter seltene Silberreiher und Kormorane. Ein Teil des Gebiets, wie die Kányavár-Insel, ist für Touristen zugänglich, während die streng geschützten Kernzonen nur mit Führung besichtigt werden können. Das Besucherzentrum in Fenékpuszta bietet umfassende Einblicke in dieses einzigartige Ökosystem.",
      hu: "A Kis-Balaton kiterjedt vizes élőhely és természetvédelmi terület a Balaton délnyugati csücskénél. Eredetileg a tó szerves része volt, de a 19. századi szabályozások és a vasútépítés következtében nagyrészt kiszáradt, ami a Balaton vízminőségének romlásához vezetett. Az 1980-as években indult meg a Kis-Balaton vízvédelmi rendszerének kiépítése, amelynek célja a Zala folyó hordalékának és tápanyagainak természetes megszűrése volt. Ma a terület mintegy 14 700 hektárt foglal el, és a Ramsari Egyezmény által nemzetközileg elismert vadvíz. Madártani szempontból felbecsülhetetlen értékű: több mint 250 madárfaj fészkel vagy pihen itt, köztük ritka kócsagok, gémek és kárókatonák. A Kányavári-sziget és környéke szabadon látogatható a turisták számára, a fokozottan védett területek azonban csak szakvezetéssel érhetők el. A fenékpusztai látogatóközpont interaktív módon mutatja be a lápvilág különleges ökoszisztémáját.",
      ro: "Micul Balaton (Kis-Balaton) este o zonă umedă extinsă și o rezervație naturală situată la extremitatea sud-vestică a Lacului Balaton din Ungaria. Inițial, făcea parte integrantă din lac, dar a fost în mare parte drenat în secolul al XIX-lea prin măsuri de reglementare, ceea ce a dus la deteriorarea calității apei din Balaton. În anii 1980, a fost construit un sistem de protecție a apei pe scară largă pentru a restabili Micul Balaton ca un bazin de filtrare natural pentru râul Zala. Astăzi, zona cuprinde aproximativ 14.700 de hectare și este protejată prin Convenția Ramsar ca zonă umedă de importanță internațională. Este un paradis pentru ornitologi, peste 250 de specii de păsări cuibărind sau odihnindu-se aici, inclusiv egrete mari și cormorani rari. O parte a zonei, cum ar fi insula Kányavár, este accesibilă turiștilor, în timp ce zonele centrale strict protejate pot fi vizitate doar cu ghid. Centrul de vizitare din Fenékpuszta oferă perspective detaliate asupra acestui ecosistem unic.",
      en: "Little Balaton (Kis-Balaton) is a vast wetland and nature reserve located at the southwestern tip of Lake Balaton in Hungary. Originally an integral bay of the main lake, it was largely drained in the 19th century due to river regulation and railway construction, which subsequently led to a decline in Lake Balaton's water quality. In the 1980s, a large-scale water protection system was implemented to restore Little Balaton as a natural filtering basin for the Zala River. Today, the area covers approximately 14,700 hectares and is recognized internationally under the Ramsar Convention. It is an ornithological treasure trove, with over 250 bird species nesting or migrating through the site, including rare great egrets and cormorants. While some areas like Kányavár Island are open to the public via scenic wooden bridges, the strictly protected core zones require guided tours. The visitor center at Fenékpuszta provides interactive insights into this unique marshland ecosystem.",
    },
    facts: {
      de: ["Vogelparadies.", "Natürliches Filtersystem.", "Kányavári-Insel.", "Büffelreservat in der Nähe."],
      hu: ["Madárparadicsom.", "Természetes szűrőrendszer.", "Kányavári-sziget.", "Bivalyrezervátum a közelben."],
      ro: ["Paradisul păsărilor.", "Sistem de filtrare natural.", "Insula Kányavári.", "Rezervație de bivoli în apropiere."],
      en: ["Bird paradise.", "Natural filter system.", "Kányavári Island.", "Buffalo reserve nearby."]
    }, image: "/poi-images/geo-kisbalaton-extra.webp",
    factsAdvanced: {
      de: ["Das Naturschutzgebiet umfasst eine Fläche von ca. 14.700 Hektar", "Über 250 Vogelarten wurden in diesem Gebiet bisher nachgewiesen", "Der Kleine Plattensee dient als natürlicher Filter für den Fluss Zala", "Die Kányavár-Insel ist über eine ikonische Holzbrücke erreichbar", "Das Gebiet gehört zum Balaton-Oberland-Nationalpark", "In der Nähe befindet sich ein berühmtes Büffelreservat (Kápolnapuszta)"],
      hu: ["A védett terület teljes kiterjedése körülbelül 14 700 hektár", "Több mint 250 madárfaj jelenlétét regisztrálták eddig a területen", "A vizes élőhely természetes szűrőként védi a Balatont a Zala vizétől", "A Kányavári-szigetet egy látványos, háromíves fahíd köti össze a parttal", "A térség a Balaton-felvidéki Nemzeti Park része", "Itt található a kápolnapusztai bivalyrezervátum is"],
      ro: ["Rezervația naturală se întinde pe o suprafață de circa 14.700 de hectare", "Peste 250 de specii de păsări au fost observate în acest habitat", "Micul Balaton funcționează ca un filtru natural pentru râul Zala", "Insula Kányavár este accesibilă printr-un pod de lemn iconic", "Zona este protejată prin Convenția internațională Ramsar", "Rezervația de bivoli de la Kápolnapuszta se află în imediata vecinătate"],
      en: ["The nature reserve spans an area of approximately 14,700 hectares", "More than 250 bird species have been documented in the area", "The wetland acts as a natural biological filter for the Zala River", "Kányavár Island is accessible via a famous triple-arched wooden bridge", "The site is an internationally protected wetland under the Ramsar Convention", "The nearby Kápolnapuszta Buffalo Reserve is the largest of its kind in Hungary"],
    },
