      hu: ["Egykori végvár.", "Barokk várkastély saroktornyokkal.", "Nyári színház.", "Zalaegerszeg közelében."],
      ro: ["Fostă cetate de frontieră.", "Castel baroc cu turnuri de colț.", "Teatru de vară.", "Lângă Zalaegerszeg."],
