      hu: ["A vár első írásos említése 1281-ből származik", "Egerváry László a 15. század végén építtette ki a négyszögletes várat", "A 16. században a Nádasdyak reneszánsz stílusú védművekkel erősítették", "Az épület jellegzetessége a négy masszív saroktorony", "A 18. században a Széchényi család barokk kastéllyá alakította", "Az Egervári Esték szabadtéri színház az országosan ismert"],
      ro: ["Castelul a fost menționat pentru prima dată în documente în 1281", "László Egerváry a transformat situl într-un castel de apă în sec. XV", "Familia Nádasdy a adăugat elemente renascentiste în secolul al XVI-lea", "Clădirea are un plan pătrat caracteristic cu patru turnuri de colț", "Transformarea barocă a avut loc în secolul al XVIII-lea", "Castelul găzduiește spectacole de teatru în aer liber în fiecare vară"],
      en: ["The castle's first written record dates back to the year 1281", "László Egerváry built the square-plan moated castle in the 15th century", "The Nádasdy family added Renaissance features in the 16th century", "The structure features four massive defensive corner towers", "The Baroque reconstruction was commissioned by the Széchényis in the 18th century", "The castle courtyard serves as a renowned summer theater venue"],
